//! syntect wrapper: theme tables, language lookup and per-block tokenization.
//!
//! Everything here is pure Rust and offline: the syntax set is a committed,
//! pre-dumped asset (`assets/highlight/syntaxes.syntect`, regenerated by
//! `scripts/regen-syntaxes`), and both themes are built from Rust constants —
//! no plist/yaml loading, no `onig`, no network at build time or at runtime.
//!
//! Caching (the R2 content-hash idea) was considered and rejected: the only
//! real cost is one `SyntaxSet::from_reader` per process, guarded by a
//! process-lifetime `OnceLock` that already spans watch-mode rebuilds.
//! Per-block content caching would add file I/O and staleness risk for
//! microseconds of re-tokenizing.

use std::io::Cursor;
use std::sync::OnceLock;

use anyhow::{anyhow, Result};
use syntect::easy::HighlightLines;
use syntect::highlighting::{Color, StyleModifier, Theme, ThemeItem, ThemeSettings};
use syntect::parsing::{SyntaxReference, SyntaxSet};

/// The curated dump: `include_bytes!` keeps it in the binary as compressed
/// bytes (zlib inside), never as parsed data at rest.
const SYNTAXES: &[u8] = include_bytes!("../../assets/highlight/syntaxes.syntect");

/// One token of one line. `color` is `None` exactly when the token renders in
/// the theme's base foreground — emit.rs leaves such runs unwrapped, which
/// keeps the emitted LaTeX small and the base text plain black.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Span {
    pub text: String,
    pub color: Option<Rgb>,
}

/// An 8-bit RGB triple, the only colour vocabulary texforge emits.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Rgb {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

impl Rgb {
    pub const fn new(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b }
    }

    /// The colour's LaTeX name: `tfxcol` + lowercase hex, so identical
    /// colours always share one `\definecolor` line.
    pub fn name(&self) -> String {
        format!("tfxcol{:02x}{:02x}{:02x}", self.r, self.g, self.b)
    }

    /// `{r,g,b}` as `color.sty`'s `rgb` fractions, three decimals.
    pub fn to_rgb_list(self) -> String {
        format!(
            "{:.3},{:.3},{:.3}",
            f64::from(self.r) / 255.0,
            f64::from(self.g) / 255.0,
            f64::from(self.b) / 255.0
        )
    }
}

impl From<Color> for Rgb {
    fn from(c: Color) -> Self {
        Self::new(c.r, c.g, c.b)
    }
}

impl From<Rgb> for Color {
    fn from(rgb: Rgb) -> Self {
        Self {
            r: rgb.r,
            g: rgb.g,
            b: rgb.b,
            a: 0xFF,
        }
    }
}

/// The two supported light themes. Dark themes are refused by design: the
/// emitted LaTeX never paints a block background (there is no page to paint
/// on), so a white-on-dark palette would print as white on paper.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HighlightTheme {
    Github,
    OneLight,
}

impl Default for HighlightTheme {
    /// `github` — the documented default.
    fn default() -> Self {
        Self::Github
    }
}

/// The valid theme names, in the order errors should list them.
pub const VALID_THEME_NAMES: [&str; 2] = ["github", "one-light"];

impl HighlightTheme {
    /// Parse a theme name from `project.toml`'s `[highlight] theme`. An
    /// unknown name fails the build, naming the offending value and every
    /// valid alternative — mirroring `DiagramStyle::parse`.
    pub fn parse(name: &str) -> Result<Self> {
        match name {
            "github" => Ok(Self::Github),
            "one-light" => Ok(Self::OneLight),
            other => anyhow::bail!(
                "Unknown code theme '{other}' — valid themes are: {}",
                VALID_THEME_NAMES.join(", ")
            ),
        }
    }

    fn spec(self) -> &'static ThemeSpec {
        match self {
            Self::Github => &GITHUB,
            Self::OneLight => &ONE_LIGHT,
        }
    }

    fn index(self) -> usize {
        match self {
            Self::Github => 0,
            Self::OneLight => 1,
        }
    }
}

/// A theme as data: the base foreground every unscoped token inherits, and a
/// scope-selector → colour table. Built into a syntect [`Theme`] once per
/// process.
struct ThemeSpec {
    name: &'static str,
    base: Rgb,
    /// `(scope selector, colour)`; deeper selectors win inside syntect's own
    /// scoring, so list order is not load-bearing.
    rules: &'static [(&'static str, Rgb)],
}

