/// Author-facing spellings → syntax names in the dump. Keys are already
/// lowercased; lookup still falls back to the raw token so `C++`/`MATLAB`
/// (case-insensitive name match) work without an entry.
const ALIASES: &[(&str, &str)] = &[
    ("py", "Python"),
    ("python3", "Python"),
    ("rs", "Rust"),
    ("js", "JavaScript"),
    ("jsx", "JSX"),
    ("ts", "TypeScript"),
    ("tsx", "TSX"),
    ("tex", "LaTeX"),
    ("latex", "LaTeX"),
    ("sh", "Bash"),
    ("zsh", "Bash"),
    ("shell", "Bash"),
    ("bash", "Bash"),
    ("md", "Markdown"),
    ("markdown", "Markdown"),
    ("dot", "Graphviz (DOT)"),
    ("gv", "Graphviz (DOT)"),
    ("graphviz", "Graphviz (DOT)"),
    ("git", "Git Diff"),
    ("yml", "YAML"),
    ("c++", "C++"),
    ("cc", "C++"),
    ("make", "Makefile"),
    ("mk", "Makefile"),
    ("rb", "Ruby"),
];

/// `lang` values that deliberately mean "plain monospace, no highlighting" —
/// the author's explicit choice, so no warning is emitted for them.
const PLAIN_LANGS: &[&str] = &["", "text", "txt", "plaintext"];

/// The curated syntax set, loaded once per process. The result is cached as a
/// `Result` so a failed load is reported once as a build error instead of
/// panicking in a `Lazy` initializer.
static SYNTAX_SET: OnceLock<Result<SyntaxSet, String>> = OnceLock::new();

/// Built themes, one slot per [`HighlightTheme`].
static THEMES: [OnceLock<Theme>; 2] = [OnceLock::new(), OnceLock::new()];

fn syntax_set() -> Result<&'static SyntaxSet> {
    let loaded = SYNTAX_SET.get_or_init(|| {
        syntect::dumps::from_reader(Cursor::new(SYNTAXES)).map_err(|e| {
            format!(
                "code listing assets failed to load ({e}) — regenerate with scripts/regen-syntaxes"
            )
        })
    });
    match loaded {
        Ok(set) => Ok(set),
        Err(message) => Err(anyhow!(message.clone())),
    }
}

fn theme_of(kind: HighlightTheme) -> &'static Theme {
    THEMES[kind.index()].get_or_init(|| {
        let spec = kind.spec();
        let scopes = spec
            .rules
            .iter()
            .map(|(selector, rgb)| ThemeItem {
                scope: selector
                    .parse()
                    .expect("theme scope selectors are compile-time constants"),
                style: StyleModifier {
                    foreground: Some((*rgb).into()),
                    background: None,
                    font_style: None,
                },
            })
            .collect();
        Theme {
            name: Some(spec.name.to_string()),
            author: Some("texforge".to_string()),
            settings: ThemeSettings {
                foreground: Some(spec.base.into()),
                background: Some(Color {
                    r: 255,
                    g: 255,
                    b: 255,
                    a: 255,
                }),
                ..ThemeSettings::default()
            },
            scopes,
        }
    })
}

/// Tokenize one block.
///
/// * `Ok(Some(lines))` — one `Vec<Span>` per line of `code` (same line
///   splitting emit.rs uses), coloured or plain-base.
/// * `Ok(None)` — the language is unknown; the caller warns (W1) and renders
///   monochrome. Never a build failure.
/// * `Err` — the committed asset itself could not be loaded (a real bug:
///   regenerate the asset).
pub fn highlight(lang: &str, code: &str, theme: HighlightTheme) -> Result<Option<Vec<Vec<Span>>>> {
    let raw = lang.trim();
    let lower = raw.to_lowercase();
    if PLAIN_LANGS.contains(&lower.as_str()) {
        // Deliberate plain block: no syntect call, no warning.
        return Ok(Some(monochrome(code)));
    }

    let set = syntax_set()?;
    let alias = ALIASES
        .iter()
        .find(|(from, _)| *from == lower)
        .map(|(_, to)| *to)
        .unwrap_or(&lower);
    let syntax = set
        .find_syntax_by_token(alias)
        .or_else(|| set.find_syntax_by_token(raw));
    let Some(syntax) = syntax else {
        return Ok(None);
    };

    Ok(Some(tokenize(set, syntax, code, theme)))
}

/// One plain span per line — the shape a monochrome block needs.
fn monochrome(code: &str) -> Vec<Vec<Span>> {
    code.split('\n')
        .map(|line| {
            vec![Span {
                text: line.to_string(),
                color: None,
            }]
        })
        .collect()
}

/// Tokenize with one [`HighlightLines`] for the whole block, so multi-line
/// state (block comments, heredocs, triple-quoted strings) carries across
/// lines.
///
/// Highlighting must never fail a build: both a syntect error **and** a
/// pattern the bundled regex engine cannot compile degrade the whole block to
/// monochrome, with a warning on stderr. The second case surfaces as a panic
/// inside syntect (`regex string should be pre-tested`) — grammars are
/// validated at regen time (`scripts/regen-syntaxes`), so this is the
/// backstop, not the mechanism.
fn tokenize(
    set: &SyntaxSet,
    syntax: &SyntaxReference,
    code: &str,
    kind: HighlightTheme,
) -> Vec<Vec<Span>> {
    // Silence the default panic hook for the duration of the catch: syntect's
    // raw message would alarm a user whose build actually succeeded. The
    // warning printed below is the user-facing text.
    let previous_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        tokenize_lines(set, syntax, code, kind)
    }));
    std::panic::set_hook(previous_hook);

    match outcome {
        Ok(Ok(lines)) => lines,
        Ok(Err(message)) => {
            eprintln!(
                "warning: syntax highlighting failed for '{}' ({message}) — rendered without \
                 highlighting",
                syntax.name
            );
            monochrome(code)
        }
        Err(_) => {
            eprintln!(
                "warning: '{}' uses a pattern the bundled highlighter cannot run — rendered \
                 without highlighting",
                syntax.name
            );
            monochrome(code)
        }
    }
}

fn tokenize_lines(
    set: &SyntaxSet,
    syntax: &SyntaxReference,
    code: &str,
    kind: HighlightTheme,
) -> Result<Vec<Vec<Span>>, String> {
    let theme = theme_of(kind);
    let base: Rgb = theme.settings.foreground.unwrap_or(Color::BLACK).into();
    let mut state = HighlightLines::new(syntax, theme);
    // Lines are fed to syntect with their trailing newline (the syntax set is
    // loaded that way, which is syntect's recommended shape).
    let mut lines = Vec::new();
    for line in code.split('\n') {
        let mut owned = String::with_capacity(line.len() + 1);
        owned.push_str(line);
        owned.push('\n');
        let spans = state
            .highlight_line(&owned, set)
            .map_err(|e| e.to_string())?;
        let mut mapped: Vec<Span> = spans
            .iter()
            .map(|(style, text)| Span {
                text: (*text).to_string(),
                color: {
                    let rgb = Rgb::from(style.foreground);
                    (rgb != base).then_some(rgb)
                },
            })
            .collect();
        // syntect keeps the newline it was fed inside the last span; emit.rs
        // owns line separation, so drop it here or it would land as a literal
        // newline inside a LaTeX paragraph.
        if let Some(last) = mapped.last_mut() {
            if let Some(trimmed) = last.text.strip_suffix('\n') {
                last.text.truncate(trimmed.len());
            }
        }
        lines.push(mapped);
    }
    Ok(lines)
}

/// Language → one-liner samples used by the closure test below. Every sample
/// must produce at least one coloured span: that is what catches a dump with
/// a missing embedded syntax (the T7 trap), because a dangling reference
/// surfaces as a parse error and the block would fall back to monochrome.
#[cfg(test)]
pub(crate) const SAMPLES: &[(&str, &str)] = &[
    ("bash", "# comment\necho \"hi\""),
    ("c", "int x = 1; // comment"),
    ("c++", "int x = 1; // comment"),
    ("clojure", "; comment\n(def x 1)"),
    ("css", "/* comment */\na { color: red; }"),
    ("diff", "--- a\n+++ b\n+added"),
    ("erlang", "% comment\nf() -> ok."),
    ("go", "package main // comment"),
    ("dot", "digraph G { a -> b }"),
    ("html", "<html><!-- comment --></html>"),
    ("haskell", "-- comment\nf x = x"),
    ("json", "{\"a\": 1}"),
    ("java", "class A { int x = 1; } // c"),
    ("js", "function f() { return 'x'; } // c"),
    ("ts", "const x: number = 1; // c"),
    ("tex", "% comment\n\\documentclass{article}"),
    ("lua", "-- comment\nlocal x = 1"),
    ("make", "# comment\ntarget:\n\techo hi"),
    ("md", "# heading\n\n```python\nx = 1\n```"),
    ("matlab", "% comment\nx = 1;"),
    ("ocaml", "(* comment *)\nlet x = 1"),
    ("php", "<?php // comment\n$x = 1;"),
    ("python", "def fib(n):\n    return n  # comment"),
    ("r", "# comment\nx <- 1"),
    ("rb", "# comment\nputs 'hi'"),
    ("rs", "fn main() { let x = 1; } // c"),
    ("sql", "SELECT 1; -- comment"),
    ("toml", "# comment\nkey = \"value\""),
    ("xml", "<?xml version=\"1.0\"?><!-- c -->"),
    ("yml", "# comment\nkey: value"),
];

#[cfg(test)]
mod tests {
    use super::*;

    fn render(lang: &str, code: &str) -> Option<Vec<Vec<Span>>> {
        highlight(lang, code, HighlightTheme::Github).unwrap()
    }

    #[test]
    fn unknown_language_is_none_not_an_error() {
        assert!(render("brainfuck", "+++").is_none());
        assert!(render("Brainfuck 9000", "+++").is_none());
        // `kt` (Kotlin) ships no grammar and is not a documented alias: like
        // every undocumented spelling it must warn, not resolve to plain text.
        assert!(render("kt", "fun main() {}").is_none());
    }

    #[test]
    fn plain_languages_are_explicitly_monochrome() {
        for lang in ["", "text", "txt", "plaintext", "  Txt "] {
            let lines = render(lang, "a\nb").expect("plain langs must resolve");
            assert_eq!(lines.len(), 2);
            assert!(lines.iter().flatten().all(|s| s.color.is_none()));
        }
    }

    #[test]
    fn python_produces_coloured_runs() {
        let lines = render("python", "def fib(n):  # comment").expect("python resolves");
        assert!(
            lines.iter().flatten().any(|s| s.color.is_some()),
            "expected at least one coloured span"
        );
    }

    #[test]
    fn aliases_resolve_to_the_shipped_syntax() {
        for (lang, expect) in [
            ("js", "JavaScript"),
            ("py", "Python"),
            ("rs", "Rust"),
            ("sh", "Bash"),
            ("zsh", "Bash"),
            ("md", "Markdown"),
            ("yml", "YAML"),
        ] {
            let lines = render(lang, "x = 1 // c").unwrap_or_else(|| panic!("{lang} must resolve"));
            assert!(!lines.is_empty());
            let _ = expect;
        }
        // Raw, case-sensitive-ish spellings still work through name matching.
        assert!(render("C++", "int x;").is_some());
    }

    /// Every `lang=` value (and alias) `docs/listings.md` publishes must
    /// resolve to a shipped syntax — an undocumented-then-unresolved spelling
    /// would silently render monochrome with a warning.
    #[test]
    fn documented_lang_spellings_resolve() {
        let documented = [
            "python",
            "py",
            "rust",
            "rs",
            "javascript",
            "js",
            "typescript",
            "ts",
            "bash",
            "sh",
            "zsh",
            "shell",
            "c",
            "c++",
            "cpp",
            "cc",
            "json",
            "yaml",
            "yml",
            "toml",
            "markdown",
            "md",
            "latex",
            "tex",
            "r",
            "sql",
            // the doc claims `sql` also matches "by name"
            "mysql",
            "postgresql",
            "clojure",
            "css",
            "diff",
            "erlang",
            "go",
            "haskell",
            "java",
            "lua",
            "matlab",
            "ocaml",
            "php",
            "ruby",
            "rb",
            "xml",
            "make",
            "mk",
            "dot",
            "graphviz",
            "gv",
            "git",
            "jsx",
            "tsx",
            // deliberate plain blocks: resolve without a warning, not to a grammar
            "text",
            "txt",
            "plaintext",
        ];
        for lang in documented {
            let resolved = highlight(lang, "x = 1 // c", HighlightTheme::Github)
                .unwrap_or_else(|e| panic!("{lang}: asset failed to load: {e}"));
            assert!(resolved.is_some(), "lang={lang} does not resolve");
        }
    }

    /// The T7 closure test: every curated language must tokenize its sample
    /// with colour — a dump missing an embedded syntax degrades to
    /// monochrome here instead of silently shipping.
    #[test]
    fn every_curated_language_tokenizes_with_colour() {
        for (lang, sample) in SAMPLES {
            let lines = highlight(lang, sample, HighlightTheme::Github)
                .unwrap_or_else(|e| panic!("{lang}: asset failed to load: {e}"));
            let lines = lines.unwrap_or_else(|| panic!("{lang} did not resolve to a syntax"));
            assert_eq!(
                lines.len(),
                sample.split('\n').count(),
                "{lang}: line count must match the input"
            );
            assert!(
                lines.iter().flatten().any(|s| s.color.is_some()),
                "{lang}: expected colour for sample {sample:?}"
            );
        }
    }

    #[test]
    fn round_trip_of_every_sample_survives_the_one_light_theme() {
        // The second theme must tokenize the same inputs; it only differs in
        // colours, but a broken selector would fail parsing for both.
        for (lang, sample) in SAMPLES {
            assert!(
                highlight(lang, sample, HighlightTheme::OneLight)
                    .unwrap_or_else(|e| panic!("{lang}: {e}"))
                    .is_some(),
                "{lang}"
            );
        }
    }

    #[test]
    fn theme_parse_names_and_error() {
        assert_eq!(
            HighlightTheme::parse("github").unwrap(),
            HighlightTheme::Github
        );
        assert_eq!(
            HighlightTheme::parse("one-light").unwrap(),
            HighlightTheme::OneLight
        );
        let err = HighlightTheme::parse("dracula").unwrap_err().to_string();
        assert!(err.contains("dracula"), "{err}");
        for name in VALID_THEME_NAMES {
            assert!(err.contains(name), "{err}");
        }
    }

    #[test]
    fn rgb_names_and_fractions() {
        let rgb = Rgb::new(0x03, 0x2f, 0x62);
        assert_eq!(rgb.name(), "tfxcol032f62");
        assert_eq!(rgb.to_rgb_list(), "0.012,0.184,0.384");
        assert_eq!(
            Rgb::new(0x6e, 0x77, 0x81).to_rgb_list(),
            "0.431,0.467,0.506"
        );
    }

    #[test]
    fn line_splitting_matches_emit() {
        // emit.rs renders `body.split('\n')`; the tokenizer must yield one
        // entry per element, blank lines included.
        let lines = highlight("python", "a\n\nb", HighlightTheme::Github)
            .unwrap()
            .unwrap();
        assert_eq!(lines.len(), 3);
        assert!(lines[1].iter().all(|s| s.text == "\n" || s.text.is_empty()));
    }
}
